249	/// The tag of an HTML element.
250	#[derive(Copy, Clone, Eq, PartialEq, Hash)]
251	pub struct HtmlTag(PicoStr);
252	
253	impl HtmlTag {
254	    /// Intern an HTML tag string at runtime.
255	    pub fn intern(string: &str) -> StrResult<Self> {
