304	impl Destination {
305	    pub fn alt_text(
306	        &self,
307	        engine: &mut Engine,
308	        styles: StyleChain,
309	        span: Span,
310	    ) -> SourceResult<EcoString> {
311	        match self {
312	            Destination::Url(url) => {
313	                let contact = url.strip_contact_scheme().map(|(scheme, stripped)| {
314	                    eco_format!("{} {stripped}", scheme.local_name_in(styles))
315	                });
316	                Ok(contact.unwrap_or_else(|| url.clone().into_inner()))
317	            }
318	            Destination::Position(pos) => {
319	                let page_nr = eco_format!("{}", pos.page.get());
320	                let page_str = PageElem::local_name_in(styles);
321	                Ok(eco_format!("{page_str} {page_nr}"))
322	            }
323	            &Destination::Location(loc) => {
324	                let fallback = |engine: &mut Engine| {
325	                    // Fall back to a generating a page reference.
326	                    let numbering =
327	                        loc.page_numbering(engine, span).unwrap_or_else(|| {
328	                            NumberingPattern::from_str("1").unwrap().into()
329	                        });
330	                    let page_nr = Counter::new(CounterKey::Page)
331	                        .display_at(engine, loc, styles, &numbering, span)?
332	                        .plain_text();
333	                    let page_str = PageElem::local_name_in(styles);
334	                    Ok(eco_format!("{page_str} {page_nr}"))
335	                };
336	
337	                // Try to generate more meaningful alt text if the location is a
338	                // refable element.
339	                if let Some(elem) = engine
340	                    .introspect(QueryFirstIntrospection(Selector::Location(loc), span))
341	                    && let Some(refable) = elem.with::<dyn Refable>()
342	                {
343	                    let counter = refable.counter();
344	                    let supplement = refable.supplement().plain_text();
345	
346	                    if let Some(numbering) = refable.numbering() {
347	                        let numbers = counter.display_at(
348	                            engine,
349	                            loc,
350	                            styles,
351	                            &numbering.clone().trimmed(),
352	                            span,
353	                        )?;
354	                        return Ok(eco_format!("{supplement} {}", numbers.plain_text()));
355	                    } else {
356	                        let page_ref = fallback(engine)?;
357	                        return Ok(eco_format!("{supplement}, {page_ref}"));
358	                    }
359	                }
360	
361	                fallback(engine)
362	            }
363	        }
364	    }
365	}
