514	/// Creates unique IDs for elements.
515	pub struct AnchorGenerator<'a> {
516	    introspector: &'a dyn Introspector,
517	    loc_counter: usize,
518	    label_counter: FxHashMap<Label, usize>,
519	}
520	
521	impl<'a> AnchorGenerator<'a> {
522	    /// Creates a new identificator.
523	    pub fn new(introspector: &'a dyn Introspector) -> Self {
524	        Self {
525	            introspector,
526	            loc_counter: 0,
527	            label_counter: FxHashMap::default(),
528	        }
529	    }
530	
531	    /// Returns a reference to the underlying introspector.
532	    pub fn introspector(&self) -> &'a dyn Introspector {
533	        self.introspector
534	    }
535	
536	    /// Generates an ID, potentially based on a label.
537	    pub fn identify(&mut self, label: Option<Label>) -> EcoString {
538	        if let Some(label) = label {
539	            let resolved = label.resolve();
540	            let text = resolved.as_str();
541	            if can_use_label_as_id(text) {
542	                if self.introspector.label_count(label) == 1 {
543	                    return text.into();
544	                }
545	
546	                let counter = self.label_counter.entry(label).or_insert(0);
547	                *counter += 1;
548	                return disambiguate(self.introspector, text, counter);
549	            }
550	        }
551	
552	        self.loc_counter += 1;
553	        disambiguate(self.introspector, "loc", &mut self.loc_counter)
554	    }
555	}
556	
557	/// Whether the label is both a valid CSS identifier and a valid URL fragment
558	/// for linking.
559	///
560	/// This is slightly more restrictive than HTML and CSS, but easier to
561	/// understand and explain.
562	fn can_use_label_as_id(label: &str) -> bool {
563	    !label.is_empty()
564	        && label.chars().all(|c| c.is_alphanumeric() || matches!(c, '-' | '_'))
565	        && !label.starts_with(|c: char| c.is_numeric() || c == '-')
566	}
567	
568	/// Disambiguates `text` with the suffix `-{counter}`, while ensuring that this
569	/// does not result in a collision with an existing label.
570	fn disambiguate(
571	    introspector: &dyn Introspector,
572	    text: &str,
573	    counter: &mut usize,
574	) -> EcoString {
575	    loop {
576	        let disambiguated = eco_format!("{text}-{counter}");
577	        if PicoStr::get(&disambiguated)
578	            .and_then(Label::new)
579	            .is_some_and(|label| introspector.label_count(label) > 0)
580	        {
581	            *counter += 1;
582	        } else {
583	            break disambiguated;
584	        }
585	    }
586	}
