598	impl EarlyLinkResolver {
599	    /// Creates a resolver that resolves links relatively to the element with
600	    /// the given location.
601	    pub fn new(base: Location, span: Span) -> Self {
602	        Self { base, span }
603	    }
604	
605	    /// Resolves a link to the given location.
606	    pub fn resolve(
607	        &self,
608	        engine: &mut Engine,
609	        location: Location,
610	    ) -> StrResult<ResolvedLink> {
611	        let from = engine.introspect(PathIntrospection(self.base, self.span));
612	        let to = engine.introspect(PathIntrospection(location, self.span));
613	        let anchor = engine
614	            .introspect(LinkAnchorIntrospection(location, self.span))
615	            .ok_or("failed to determine link anchor")?;
616	
617	        Ok(match (from, to) {
618	            // This is the normal case in single file export.
619	            (None, None) => ResolvedLink::Local { anchor },
620	            // This is the normal case in bundle export.
621	            (Some(from), Some(to)) => {
622	                if from == to {
623	                    ResolvedLink::Local { anchor }
624	                } else {
625	                    ResolvedLink::Cross { from, to, anchor }
626	                }
627	            }
628	            // This can, for instance, happen when trying to link to
629	            // metadata that is not within a document (top-level in the
630	            // bundle).
631	            (Some(_), None) => {
632	                bail!("link destination is not within a document")
633	            }
634	            // This is rather unlikely because we can't resolve a link rule
635	            // in a non-file. It could happen in a non-convergent case.
636	            (None, Some(_)) => bail!("failed to resolve cross-link"),
637	        })
638	    }
639	}
